import assert from 'node:assert/strict';
import mime from '../../dist/src/index.js';

// A file name holding a line feed must still be typed by the extension after its last dot.
assert.equal(mime.getType('LINE\nFEED.png'), 'image/png');
assert.equal(mime.getType('/path/to/LINE\nFEED.png'), 'image/png');

// Ordinary names are unchanged.
assert.equal(mime.getType('report.html'), 'text/html');
assert.equal(mime.getType('/path/to/.config.json'), 'application/json');
assert.equal(mime.getType('/path/to/file'), null);

console.log('visible check passed');

import assert from 'node:assert/strict';
import zlib from 'node:zlib';
import { Inflate } from '../../src/index.ts';

// A compressed stream can end before the caller's data does: trailing chunks are no-ops that
// report the decode's outcome and leave the delivered result intact.
const stream = zlib.deflateSync(Buffer.from('payload'));
const inflator = new Inflate();
assert.equal(inflator.push(stream), true);
assert.equal(inflator.ended, true);
assert.equal(inflator.push(new Uint8Array([1, 2, 3])), true);
assert.equal(Buffer.from(inflator.result).toString(), 'payload');
assert.equal(inflator.err, 0);

console.log('visible check passed');
